int* findDiagonalOrder(int** mat, int matSize, int* matColSize, int* returnSize) {
    if (matSize == 0 || matColSize[0] == 0) {
        *returnSize = 0;
        return NULL;
    }
    int m = matSize, n = matColSize[0];
    int total = m * n;
    int *result = (int*)malloc((size_t)total * sizeof(int));
    int row = 0, col = 0, direction = 1;

    for (int k = 0; k < total; ++k) {
        result[k] = mat[row][col];

        if (direction == 1) {
            if (col == n - 1) {
                ++row;
                direction = -1;
            } else if (row == 0) {
                ++col;
                direction = -1;
            } else {
                --row;
                ++col;
            }
        } else {
            if (row == m - 1) {
                ++col;
                direction = 1;
            } else if (col == 0) {
                ++row;
                direction = 1;
            } else {
                ++row;
                --col;
            }
        }
    }
    *returnSize = total;
    return result;
}

